(async () => { const H = {'Content-Type':'application/json','X-Gigg-CSRF':'1'}; const j = async (m, u, b) => { const r = await fetch('/api/v1' + u, {method: m, headers: H, body: JSON.stringify(b)}); return r.status; };
 const out = [];
 out.push(await j('POST','/workspaces',{slug:'atlas',name:'Atlas'}));
 out.push(await j('POST','/workspaces',{slug:'meridian',name:'Meridian'}));
 out.push(await j('POST','/workspaces/atlas/projects',{slug:'main',name:'Main',key:'ATM'}));
 out.push(await j('POST','/workspaces/atlas/projects',{slug:'billing',name:'Billing',key:'BIL'}));
 out.push(await j('POST','/workspaces/meridian/projects',{slug:'main',name:'Main',key:'MVM'}));
 out.push(await j('POST','/workspaces/meridian/projects',{slug:'scripts',name:'Scripts',key:'SCR'}));
 for (const w of ['atlas','meridian']) { const r = await fetch('/api/v1/workspaces/' + w + '/projects'); for (const pr of (await r.json()).items) out.push(await j('POST','/projects/' + pr.id + '/gigs',{title:'Where ' + w + '/' + pr.slug})); }
 out.push(await j('POST','/projects/1/gigs',{title:'Nightly backup check, always run',priority:2,always_run:true,assignees:[2]}));
 out.push(await j('POST','/projects/1/gigs',{title:'A bolt gig with a deliberately long title that has to wrap onto a second and a third line to test the card top row',priority:3,always_run:true,assignees:[2]}));
 const t = {freq:'daily',tz:'UTC',window_start:'07:00',window_minutes:60};
 out.push(await j('POST','/workspaces/atlas/schedules',{name:'Mornings A',...t}));
 out.push(await j('POST','/workspaces/meridian/schedules',{name:'Mornings B',...t}));
 out.push(await j('POST','/workspaces/meridian/schedules',{name:'Evenings',freq:'daily',tz:'UTC',window_start:'19:00',window_minutes:60}));
 out.push(await j('POST','/workspaces/meridian/schedules',{name:'Quarterly planning review for the whole platform and operations team',freq:'weekly',weekdays:[1,3,5],tz:'UTC',window_start:'09:00',window_minutes:90,lead_minutes:60}));
 out.push(await j('POST','/workspaces/atlas/templates',{name:'Triage',title:'Triage the inbox'}));
 out.push(await j('POST','/workspaces/meridian/templates',{name:'Triage',title:'Triage the inbox'}));
 out.push(await j('POST','/workspaces/meridian/templates',{name:'Quarterly planning review template with a long name to wrap',title:'Review the quarter'}));
 out.push(await j('POST','/workspaces/scout/errands',{name:'Disk check',command:'df -h',rule:{freq:'daily',tz:'UTC',window_start:'03:00',window_minutes:60},worker:'scout'}));
 return out; })()
